INSERT INTO public.about_pages (id,locale,headline,intro,body,status) VALUES ('e6231ea4-07aa-4c1a-ab9e-43caa2fa8b62','en','About',NULL,'{"values": {"items": [{"title": "Quality over speed", "description": "I prefer delivering a robust and well-tested solution over a quick but fragile one. Technical shortcuts always cost more in the long run."}, {"title": "Systematic documentation", "description": "Every project I deliver includes complete documentation: architecture, technical choices, deployment runbooks, and user guides. Code should be understandable by someone other than me."}, {"title": "Collaboration and knowledge transfer", "description": "I enjoy working in teams and sharing my knowledge. Training a user or admin to properly use a solution is an integral part of my mission."}, {"title": "User-centered approach", "description": "The best technical solution has no value if it doesn''t solve the user''s real problem. I listen first, design second."}], "title": "My Professional Values"}, "journey": {"title": "My Journey", "paragraphs": ["I obtained my TAI diploma (IT Support Technician, RNCP Level 4) at GRETA du Val d''Oise in July 2022, following practical training at Lycée Louis Jouvet in Taverny. There I developed skills in user support, network configuration, virtualization, and Active Directory management.", "From October 2022 to June 2023, I completed the TSSR program (Higher Technician in Systems & Networks, RNCP Level 5) at GRETA du Val d''Oise, including a four-month internship at MIDRANGE GROUP (February – May 2023). I provided technical support for 50+ workstations, deployed 200 Dell machines via Windows Autopilot, administered a full Windows Server 2022 environment (AD DS, DNS, DHCP, GPO, PXE), set up a PfSense firewall with Squid proxy, and managed backups with Acronis Cyber Protect Cloud.", "While completing the TSSR, I began exploring Salesforce independently from 2022 — Trailhead, documentation, personal projects. That curiosity led me to specialize. From October 2023 to September 2025, I completed my work-study at LD Digitales (remote) as a Salesforce Developer, alongside the Développeur Concepteur Logiciel title from OpenClassrooms (RNCP Level 6). I built and maintained 10+ Apex classes and batch jobs, created 20+ automation Flows (reducing manual workload by 30%), designed reusable LWC components, and implemented CI/CD pipelines with Salesforce CLI and GitHub Actions. Since October 2025, I am in a permanent role (CDI) at LD Digitales — a natural continuation of the work-study."]}, "passions": {"title": "Outside of Work", "paragraphs": ["When I''m not coding, you''ll likely find me reading technical blogs (I love following Salesforce release notes!), contributing to help forums, or tinkering with personal projects in Python or TypeScript.", "I''m also passionate about cybersecurity — a passion inherited from my years in systems administration. I regularly participate in CTFs (Capture The Flag) and try to stay updated on the latest threats and best practices.", "Finally, I love traveling and discovering new cultures. Working with distributed international teams across multiple time zones doesn''t scare me — on the contrary, it''s a constant enrichment."]}, "goals2026": {"items": ["Obtain Salesforce certifications in 2026: ADM-201, App Builder, CPQ Admin, Marketing Cloud Engagement Admin", "Launch independent consulting activity (portage salarial) in early 2027", "Ship first versions of OrgDocs and SFRelease — two SaaS products in the Salesforce ecosystem", "Actively contribute to the Salesforce community: technical blog, Trailblazer Community, open source", "Build an international client base (France, UK, European market — remote)"], "title": "2026 Goals"}, "introduction": "Salesforce Developer & Consultant in a permanent role (CDI) at LD Digitales, I design reliable, secure, and maintainable solutions. My systems & networks background (TAI, TSSR, MIDRANGE GROUP internship) taught me to approach the platform with an operations mindset: CI/CD, security, documentation, and automation."}'::jsonb,'published') ON CONFLICT (locale) DO UPDATE SET headline=EXCLUDED.headline,intro=EXCLUDED.intro,body=EXCLUDED.body,status=EXCLUDED.status;
INSERT INTO public.about_pages (id,locale,headline,intro,body,status) VALUES ('012cda78-2c25-4906-bd51-440d2193c487','fr','À propos',NULL,'{"values": {"items": [{"title": "Qualité avant vitesse", "description": "Je préfère livrer une solution robuste et bien testée qu''une solution rapide mais fragile. Les raccourcis techniques coûtent toujours plus cher à long terme."}, {"title": "Documentation systématique", "description": "Chaque projet que je livre inclut une documentation complète : architecture, choix techniques, runbooks de déploiement et guides utilisateurs. Le code doit être compréhensible par quelqu''un d''autre que moi."}, {"title": "Collaboration et transmission", "description": "J''aime travailler en équipe et partager mes connaissances. Former un utilisateur ou un admin à utiliser correctement une solution fait partie intégrante de ma mission."}, {"title": "Approche centrée utilisateur", "description": "La meilleure solution technique n''a aucune valeur si elle ne résout pas le vrai problème de l''utilisateur. J''écoute d''abord, je conçois ensuite."}], "title": "Mes valeurs professionnelles"}, "journey": {"title": "Mon parcours", "paragraphs": ["J''ai obtenu mon titre TAI (Technicien d''Assistance Informatique, niveau 4 RNCP) au GRETA du Val d''Oise en juillet 2022, après une formation pratique au Lycée Louis Jouvet à Taverny. J''y ai acquis les bases du support utilisateur, de la configuration réseau, de la virtualisation et de la gestion Active Directory.", "D''octobre 2022 à juin 2023, j''ai suivi la formation TSSR (Technicienne Supérieure Systèmes & Réseaux, niveau 5 RNCP) au GRETA du Val d''Oise, complétée par un stage de quatre mois chez MIDRANGE GROUP (février – mai 2023). J''y ai assuré le support technique de plus de 50 postes, déployé 200 workstations Dell via Windows Autopilot, administré un environnement Windows Server 2022 (AD DS, DNS, DHCP, GPO, PXE), mis en place un pare-feu PfSense avec proxy Squid, et géré les sauvegardes avec Acronis Cyber Protect Cloud.", "En parallèle de la TSSR, j''ai commencé à explorer Salesforce de façon autonome dès 2022 — Trailhead, documentation, projets personnels. Cette curiosité m''a convaincue de me spécialiser. D''octobre 2023 à septembre 2025, j''ai réalisé mon alternance chez LD Digitales (en remote) en tant que développeuse Salesforce, en parallèle du titre Développeur Concepteur Logiciel d''OpenClassrooms (niveau 6 RNCP). J''ai développé des classes Apex, des composants LWC réutilisables, des Flows d''automatisation et des pipelines CI/CD avec Salesforce CLI et GitHub Actions. Depuis octobre 2025, je suis en CDI chez LD Digitales — continuité naturelle de l''alternance."]}, "passions": {"title": "En dehors du travail", "paragraphs": ["Quand je ne code pas, vous me trouverez probablement en train de lire des blogs techniques (j''adore suivre les releases notes de Salesforce !), de contribuer à des forums d''entraide, ou de bidouiller des projets perso en Python ou TypeScript.", "Je suis également passionnée par la cybersécurité — une passion héritée de mes années en administration systèmes. Je participe régulièrement à des CTF (Capture The Flag) et j''essaie de rester à jour sur les dernières menaces et bonnes pratiques.", "Enfin, j''aime voyager et découvrir de nouvelles cultures. Travailler avec des équipes internationales distribuées sur plusieurs fuseaux horaires ne me fait pas peur — au contraire, c''est un enrichissement constant."]}, "goals2026": {"items": ["Obtenir les certifications Salesforce 2026 : ADM-201, App Builder, CPQ Admin, Marketing Cloud Engagement Admin", "Lancer mon activité de consultante indépendante (portage salarial) début 2027", "Publier les premières versions de OrgDocs et SFRelease — deux SaaS dans l''écosystème Salesforce", "Contribuer activement à la communauté Salesforce : blog technique, Trailblazer Community, open source", "Développer une clientèle internationale (France, UK, marché européen en remote)"], "title": "Objectifs 2026"}, "introduction": "Développeuse & consultante Salesforce en CDI chez LD Digitales, je conçois des solutions fiables, sécurisées et maintenables. Mon bagage en systèmes & réseaux (TAI, TSSR, stage MIDRANGE GROUP) m''a appris à aborder la plateforme avec une logique d''exploitation : CI/CD, sécurité, documentation et automatisation."}'::jsonb,'published') ON CONFLICT (locale) DO UPDATE SET headline=EXCLUDED.headline,intro=EXCLUDED.intro,body=EXCLUDED.body,status=EXCLUDED.status;
